 if (!vaVars.isNASS) {
 vaSystem.sendSkillPickerControl("", {"hideShowMeEverything": false, "appendPromotedSkillsToMsg": false});
 } else {
 // experience is NASS
 var shouldShowAllOptions = gs.getProperty("sn_nowassist_va.enable_nass_show_all_options", "false") == "true";

 if (vaSystem.hasPromotedSkills()) {
 // and has promoted skills then send skill picker
 vaSystem.sendSkillPickerControl("", {"hideShowMeEverything": !shouldShowAllOptions, "appendPromotedSkillsToMsg": false });
 } else if (gs.getProperty("sn_nowassist_va.enable_suggested_queries", "true") == "true") {
 // and does not have promoted skills, then send suggested query picker (if active)
 vaSystem.sendQueryPickerControl();
 }else{
 vaSystem.sendSkillPickerControl("", {"hideShowMeEverything": !shouldShowAllOptions});
 }
 }
})()","stepType":"ScriptAction","applicability":{"mode":"query","value":""},"cardMetadata":{"mode":"card","metadataScript":"","cardTemplate":"","cardFields":{},"cardDefinition":{}}},"5f685458099a422c9d494f6335dc2a48":{"id":"5f685458099a422c9d494f6335dc2a48","stepType":"Decision","name":"Search term already exists?","cardMetadata":{"mode":"card","metadataScript":"","cardTemplate":"","cardFields":{},"cardDefinition":{}}},"41cacf79cbe6474a92de594d504ca78f":{"id":"41cacf79cbe6474a92de594d504ca78f","name":"Skill discovery","script":"(function execute() {
