","stepType":"ScriptAction","applicability":{"value":"","mode":"query"},"cardMetadata":{"mode":"card","metadataScript":"","cardTemplate":"","cardFields":{},"cardDefinition":{}}},"66928c5c283d42f7ab0e22d4c1735951":{"id":"66928c5c283d42f7ab0e22d4c1735951","stepType":"ScriptOutput","name":"Send Greeting Message","output_type":"single_part","script":"(function execute() {
 var aisHelper = new sn_nowassist_va.NowAssistAISearchHelper();
 var logger = aisHelper.getLogger(aisHelper.getLoggerContext(vaSystem));
 vaVars.isNASS = vaSystem.isNASSConversation();
 var greeting = new sn_cs.SinglePartOutMsg();
 var userName = '';
	 try {
 if (gs.isLoggedIn()) {
 userName = vaInputs.user.first_name.getDisplayValue() ? vaInputs.user.first_name.getDisplayValue() : gs.getUser().getFirstName();
 }
	 } catch (error) {
		 logger.error('[NowAssistGreetingHelper] Error trying to derive name of user for conversation: {conversation}');
	 }
 if (gs.isLoggedIn() && !(userName)){
 userName = 'user';
 }
 var configuredGreeting = global.NowAssistGreetingHelper.constructGreetingMessage({
 userName: userName,
 requesterLang: vaContext.getRequesterLang(),
 greetingMessage: vaSystem.getContextProfileMessage('greeting'),
 greetingGuestMessage: vaSystem.getContextProfileMessage('greeting_guest'),
 channel: getCurrentChannel()
 });
 if (configuredGreeting.type === 'html') {
 greeting.setHtmlPart(configuredGreeting.message);
 } else if (configuredGreeting.type === 'json') {
 greeting.setAnimationPayloadPart(configuredGreeting.message);
 } else {
 greeting.setTextPart(configuredGreeting.message);
 }
 return greeting;
})()

function getCurrentChannel () {
 var channel = vaContext.deviceType;
 if (channel == "mweb") {
 // Sends either self_service or chat_client. Need this to differentiate b/w web client experiences
 return vaContext.experience;
 }
 return channel;
}","applicability":{"value":"","mode":"query"},"cardMetadata":{"mode":"card","metadataScript":"","cardTemplate":"","cardFields":{},"cardDefinition":{}}},"efb3f11975e7485f8fcf827581879858":{"id":"efb3f11975e7485f8fcf827581879858","name":"set agent context","script":"(function execute() {
 vaVars.global_agentContext = JSON.stringify({
 "conversationId": vaSystem.getConversationId()
 });
})()
